67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that contains
75	     * at least one dot. Whitespace and additional {@code @} characters are disallowed.
76	     */
77	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
78	
79	    /**
80	     * Disposable email domains that are not accepted for an owner. An email whose domain (the part
81	     * after the {@code @}, compared case-insensitively) is listed here is rejected with a 400.
82	     */
83	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
84	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
85	
86	    /**
87	     * Dedicated audit logger. Successful owner creation emits a single line here carrying the new
88	     * owner's id, customer code, registration date and membership level, so audit side-effects can
89	     * be observed independently of the HTTP response.
90	     */
91	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
92	
93	    /**
94	     * Common street-type abbreviations expanded during address normalization. Keys and values are
95	     * upper-cased, matching the state of the address after whitespace and case normalization.
96	     */
97	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
98	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
99	
100	    /**
101	     * Required national-number length per E.164 country calling code. After normalization the leading
102	     * country code is stripped and the remaining national digits must match the expected count exactly
103	     * (e.g. {@code +61} requires 9 national digits, {@code +1} requires 10). Country codes not listed
104	     * here are only subject to the generic E.164 length bounds.
105	     */
106	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
107	        Map.of("1", 10, "61", 9);
108	
109	    /**
110	     * Fixed city-to-region table used to validate an owner's postcode. Cities not listed have no
111	     * known region and accept any well-formed (4-digit) postcode.
112	     */
113	    private static final Map<String, String> CITY_REGION =
114	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
115	
116	    /**
117	     * Inclusive 4-digit postcode range {@code [low, high]} allowed for each region: NSW 2000-2099,
118	     * VIC 3000-3099, QLD 4000-4099. A supplied postcode outside its city's region range is rejected.
119	     */
120	    private static final Map<String, int[]> REGION_POSTCODES =
121	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
122	
123	    private final ClinicService clinicService;
124	
125	    private final OwnerMapper ownerMapper;
126	
127	    private final PetMapper petMapper;
128	
129	    private final VisitMapper visitMapper;
130	
131	    public OwnerRestControllerV1(ClinicService clinicService,
132	                                 OwnerMapper ownerMapper,
133	                                 PetMapper petMapper,
134	                                 VisitMapper visitMapper) {
135	        this.clinicService = clinicService;
136	        this.ownerMapper = ownerMapper;
137	        this.petMapper = petMapper;
138	        this.visitMapper = visitMapper;
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
144	        Collection<Owner> owners;
145	        if (lastName != null) {
146	            owners = this.clinicService.findOwnerByLastName(lastName);
147	        } else {
148	            owners = this.clinicService.findAllOwners();
149	        }
150	        if (owners.isEmpty()) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
159	        Owner owner = this.clinicService.findOwnerById(ownerId);
160	        if (owner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
169	        validateRequiredOwnerFields(ownerFieldsDto);
170	        HttpHeaders headers = new HttpHeaders();
171	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
172	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
173	        owner.setTelephone(normalizedTelephone);
174	        owner.setEmail(normalizeEmail(owner.getEmail()));
175	        owner.setAddress(normalizeAddress(owner.getAddress()));
176	        validatePostcode(owner.getPostcode(), owner.getCity());
177	        rejectFutureRegistrationDate(owner.getRegistrationDate());
178	        LocalDate effectiveRegistrationDate =
179	            owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
180	        owner.setRegistrationDate(rollToBusinessDay(effectiveRegistrationDate));
181	        rejectDailyLimitReached(owner.getRegistrationDate());
182	        rejectCityAtCapacity(owner.getCity());
183	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
184	        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
185	        rejectDuplicateIdentity(owner, sharesHousehold);
186	        assignPossibleDuplicate(owner, normalizedTelephone, sharesHousehold);
187	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
188	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
189	        owner.setHouseholdSize(countHousehold(owner.getHouseholdId()));
190	        owner.setCustomerCode(buildCustomerCode(owner, normalizedTelephone));
191	        this.clinicService.saveOwner(owner);
192	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
193	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
194	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
195	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
196	        headers.setLocation(UriComponentsBuilder.newInstance()
197	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
198	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
