431	    /**
432	     * Validates a supplied owner postcode. The postcode is optional: a {@code null} value is
433	     * accepted and the request stays backward-compatible. When present it must be a 4-digit value,
434	     * and must fall within the inclusive range allowed for the owner's city region per the fixed
435	     * {@link #CITY_REGION} / {@link #REGION_POSTCODES} tables (NSW 2000-2099, VIC 3000-3099,
436	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode. The value is stored
437	     * and returned exactly as given.
438	     *
439	     * @param postcode the submitted postcode, may be {@code null} when absent
440	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
441	     * @throws InvalidOwnerFieldsException if a present postcode is not 4 digits or is out of range
442	     */
443	    private void validatePostcode(String postcode, String city) {
444	        if (postcode == null) {
445	            return;
446	        }
447	        if (!postcode.matches("[0-9]{4}")) {
448	            throw new InvalidOwnerFieldsException(List.of("postcode"));
449	        }
450	        String region = city == null ? null : CITY_REGION.get(city);
451	        if (region == null) {
452	            return;
453	        }
454	        int[] range = REGION_POSTCODES.get(region);
455	        int value = Integer.parseInt(postcode);
456	        if (value < range[0] || value > range[1]) {
457	            throw new InvalidOwnerFieldsException(List.of("postcode"));
458	        }
459	    }
