461	    /**
462	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
463	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
464	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
465	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
466	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
467	     *
468	     * @param telephone the raw telephone value from the submitted owner payload
469	     * @return the normalized E.164 telephone number
470	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
471	     */
472	    private String normalizeTelephone(String telephone) {
473	        String raw = telephone == null ? "" : telephone.strip();
474	        boolean hasCountryCode = raw.startsWith("+");
475	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
476	        String digits;
477	        if (hasCountryCode) {
478	            digits = cleaned.substring(1);
479	        } else {
480	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
481	            digits = "61" + national;
482	        }
483	        if (!digits.matches("[0-9]{8,15}")) {
484	            throw new InvalidOwnerFieldsException(List.of("telephone"));
485	        }
486	        validateNationalNumberLength(digits);
487	        return "+" + digits;
488	    }
489	
490	    /**
491	     * Validates that the national-number portion of a normalized E.164 number (the digits after the
492	     * country calling code) has the exact length required for that country. The country code is matched
493	     * against {@link #NATIONAL_NUMBER_LENGTHS} (e.g. {@code +61} requires 9 national digits, {@code +1}
494	     * requires 10). Numbers whose country code is not listed are left to the generic length bounds.
495	     *
496	     * @param digits the normalized E.164 digits, without the leading {@code '+'}
497	     * @throws InvalidOwnerFieldsException if the national-number length is wrong for the country code
498	     */
499	    private void validateNationalNumberLength(String digits) {
500	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
501	            String countryCode = entry.getKey();
502	            if (digits.startsWith(countryCode)) {
503	                int nationalLength = digits.length() - countryCode.length();
504	                if (nationalLength != entry.getValue()) {
505	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
506	                }
507	                return;
508	            }
509	        }
510	    }
511	
512	    /**
513	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
514	     * returning {@code null} when the value cannot form a valid E.164 number.
515	     *
516	     * @param telephone an existing owner's stored telephone value
517	     * @return the E.164 form, or {@code null} if it cannot be normalized
518	     */
519	    private String toE164OrNull(String telephone) {
520	        try {
521	            return normalizeTelephone(telephone);
522	        } catch (InvalidOwnerFieldsException ex) {
523	            return null;
524	        }
525	    }
