527	    /**
528	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
529	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
530	     * accepted value is trimmed and lower-cased before it is stored and returned.
531	     *
532	     * @param email the raw email value from the submitted owner payload, may be {@code null}
533	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
534	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
535	     *         or if its domain is on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS})
536	     */
537	    private String normalizeEmail(String email) {
538	        if (email == null) {
539	            return null;
540	        }
541	        String trimmed = email.strip();
542	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
543	            throw new InvalidOwnerFieldsException(List.of("email"));
544	        }
545	        String normalized = trimmed.toLowerCase(Locale.ROOT);
546	        String domain = normalized.substring(normalized.indexOf('@') + 1);
547	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
548	            throw new InvalidOwnerFieldsException(List.of("email"));
549	        }
550	        return normalized;
551	    }
