553	    /**
554	     * Rejects creating an owner that would be a second member of an existing household. The household
555	     * is keyed on {@code (lastName, postcode)} through the deterministic {@link #householdId}, so any
556	     * existing owner carrying the same {@code householdId} makes the owner being created a household
557	     * duplicate. Such an owner is rejected with a 409, <em>unless</em> the request opts into
558	     * {@code sharesHousehold}: a declared household member deliberately bypasses this block and is
559	     * created as an additional member of the household.
560	     *
561	     * @param owner the owner being created, whose computed household id is matched
562	     * @param sharesHousehold whether the request declared the owner a shared-household member
563	     * @throws DuplicateOwnerIdentityException if another owner already belongs to the same household
564	     */
565	    private void rejectDuplicateIdentity(Owner owner, boolean sharesHousehold) {
566	        if (sharesHousehold) {
567	            return;
568	        }
569	        String householdId = owner.getHouseholdId();
570	        boolean duplicate = householdId != null && this.clinicService.findAllOwners().stream()
571	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
572	        if (duplicate) {
573	            throw new DuplicateOwnerIdentityException(householdId);
574	        }
575	    }
