577	    /**
578	     * Flags a soft ("possible") duplicate on the owner being created. Unlike a hard duplicate (which is
579	     * rejected outright by {@link #rejectDuplicateIdentity}), a soft duplicate is still created: it is an
580	     * owner that is not a hard duplicate but shares an existing owner's last name (compared
581	     * case-insensitively, see {@link #normalizeForComparison}) and postcode while carrying a <em>different</em>
582	     * telephone. When such an existing owner is found, {@code possibleDuplicate} is set {@code true} and
583	     * {@code possibleDuplicateOf} is set to that owner's id (the earliest by id when several match); otherwise
584	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} stays {@code null}. Both values
585	     * are snapshotted on the owner so they reflect the population as it stood when the owner was created.
586	     *
587	     * <p>A declared household member (a request that set {@code sharesHousehold} to bypass the household
588	     * duplicate block) is never a <em>suspected</em> duplicate: it is knowingly created as another member
589	     * of the household, so {@code possibleDuplicate} is left {@code false} and {@code possibleDuplicateOf}
590	     * {@code null} without consulting the existing population.
591	     *
592	     * @param owner the owner being created, whose last name and postcode are matched
593	     * @param normalizedTelephone the E.164 telephone of the owner being created
594	     * @param sharesHousehold whether the request declared the owner a shared-household member
595	     */
596	    private void assignPossibleDuplicate(Owner owner, String normalizedTelephone, boolean sharesHousehold) {
597	        if (sharesHousehold) {
598	            owner.setPossibleDuplicateOf(null);
599	            owner.setPossibleDuplicate(false);
600	            return;
601	        }
602	        String postcode = owner.getPostcode();
603	        Integer matchId = null;
604	        if (postcode != null) {
605	            String lastName = normalizeForComparison(owner.getLastName());
606	            for (Owner existing : this.clinicService.findAllOwners()) {
607	                if (postcode.equals(existing.getPostcode())
608	                    && lastName.equals(normalizeForComparison(existing.getLastName()))
609	                    && !normalizedTelephone.equals(toE164OrNull(existing.getTelephone()))
610	                    && existing.getId() != null
611	                    && (matchId == null || existing.getId() < matchId)) {
612	                    matchId = existing.getId();
613	                }
614	            }
615	        }
616	        owner.setPossibleDuplicateOf(matchId);
617	        owner.setPossibleDuplicate(matchId != null);
618	    }
