620	    /**
621	     * The maximum number of owners a single city may contain. Once a city already holds this many
622	     * owners, creating another owner in that city is rejected.
623	     */
624	    private static final int MAX_OWNERS_PER_CITY = 50;
625	
626	    /**
627	     * Rejects creating an owner in a city that already contains {@link #MAX_OWNERS_PER_CITY} or more
628	     * owners. Existing owners' cities are compared case-insensitively with surrounding and repeated
629	     * internal whitespace collapsed (see {@link #normalizeForComparison}), matching the per-city
630	     * counting used elsewhere.
631	     *
632	     * @param city the city of the owner being created
633	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
634	     */
635	    /**
636	     * The maximum number of owners that may be registered on a single day. Once this many owners
637	     * already share a {@code registrationDate}, creating another owner for that day is rejected.
638	     */
639	    private static final int MAX_OWNERS_PER_DAY = 100;
640	
641	    /**
642	     * Rejects creating an owner on a day that has already reached {@link #MAX_OWNERS_PER_DAY} or more
643	     * owner registrations. Existing owners are counted by their {@code registrationDate} matching the
644	     * registration date of the owner being created.
645	     *
646	     * @param registrationDate the registration date of the owner being created
647	     * @throws DailyOwnerLimitExceededException if the day has already reached the maximum number of owners
648	     */
649	    /**
650	     * Rolls an effective registration date forward onto a business day. A registration date must fall
651	     * on a weekday: when the supplied or defaulted date is a Saturday or Sunday it is rolled forward to
652	     * the next Monday and that adjusted date becomes the owner's {@code registrationDate}. A weekday date
653	     * is returned unchanged. Every value derived from the registration date (the daily create-limit
654	     * count, the membership number's year segment, and so on) uses this adjusted date.
655	     *
656	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
657	     * @return the same date if it is a weekday, otherwise the following Monday
658	     */
659	    /**
660	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server's
661	     * current date. A registration date is not permitted to lie in the future; a {@code null} date
662	     * (defaulted to the server date) and any date on or before today are accepted. The check runs
663	     * against the date exactly as supplied, before it is rolled forward onto a business day.
664	     *
665	     * @param registrationDate the registration date supplied in the request, may be {@code null}
666	     * @throws FutureRegistrationDateException if the supplied date is after the server date
667	     */
668	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
669	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
670	            throw new FutureRegistrationDateException(registrationDate);
671	        }
672	    }
673	
674	    private LocalDate rollToBusinessDay(LocalDate date) {
675	        DayOfWeek day = date.getDayOfWeek();
676	        if (day == DayOfWeek.SATURDAY) {
677	            return date.plusDays(2);
678	        }
679	        if (day == DayOfWeek.SUNDAY) {
680	            return date.plusDays(1);
681	        }
682	        return date;
683	    }
