685	    private void rejectDailyLimitReached(LocalDate registrationDate) {
686	        long ownersToday = this.clinicService.findAllOwners().stream()
687	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
688	            .count();
689	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
690	            throw new DailyOwnerLimitExceededException(registrationDate);
691	        }
692	    }
