694	    /**
695	     * The number of owners that must already share a {@code registrationDate} before a newly created
696	     * owner for that day is flagged with a bulk-signup warning. Once more than this many owners have
697	     * been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
698	     */
699	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
