701	    /**
702	     * Determines whether the owner being created should carry a bulk-signup warning. The warning is
703	     * raised when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for
704	     * the same registration date at the time this owner is created. Existing owners are counted by their
705	     * {@code registrationDate} matching the registration date of the owner being created, mirroring the
706	     * daily create-limit accumulation.
707	     *
708	     * @param registrationDate the registration date of the owner being created
709	     * @return {@code true} if the day already holds more than the threshold number of owners
710	     */
711	    private boolean isBulkSignupDay(LocalDate registrationDate) {
712	        long ownersToday = this.clinicService.findAllOwners().stream()
713	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
714	            .count();
715	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
716	    }
717	
718	    private void rejectCityAtCapacity(String city) {
719	        String normalizedCity = normalizeForComparison(city);
720	        long ownersInCity = this.clinicService.findAllOwners().stream()
721	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
722	            .count();
723	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
724	            throw new OwnerCityCapacityExceededException(city);
725	        }
726	    }
727	
728	    /**
729	     * Counts how many owners belong to the household the owner being created has just been assigned to,
730	     * inclusive of that owner. Existing owners are matched by their {@code householdId} equalling the
731	     * given identifier; the owner being created is added on because it is counted before being persisted.
732	     * An owner that did not opt into a shared household (its {@code householdId} is {@code null}) is a
733	     * household of one. The value is snapshotted on the owner.
734	     *
735	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
736	     * @return the number of household members, including the owner being created
737	     */
738	    private int countHousehold(String householdId) {
739	        if (householdId == null) {
740	            return 1;
741	        }
742	        long existing = this.clinicService.findAllOwners().stream()
743	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
744	            .count();
745	        return (int) existing + 1;
746	    }
747	
748	    /**
749	     * Derives the deterministic household identifier for a given last name and postcode: the first 12
750	     * hex characters of the SHA-256 digest of {@code '<normalizedLastName>|<postcode>'}, where the last
751	     * name is normalized for case- and whitespace-insensitive comparison (see
752	     * {@link #normalizeForComparison}) and a {@code null} postcode contributes an empty segment. Every
753	     * owner that shares a last name and postcode therefore resolves to the exact same identifier,
754	     * regardless of creation order, making them members of one household.
755	     *
756	     * @param lastName the owner's last name
757	     * @param postcode the owner's postcode, may be {@code null}
758	     * @return the deterministic household identifier
759	     */
760	    private String householdId(String lastName, String postcode) {
761	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
762	        try {
763	            byte[] digest = MessageDigest.getInstance("SHA-256")
764	                .digest(key.getBytes(StandardCharsets.UTF_8));
765	            StringBuilder hex = new StringBuilder();
766	            for (int i = 0; i < 6; i++) {
767	                hex.append(String.format("%02x", digest[i]));
768	            }
769	            return hex.toString();
770	        } catch (NoSuchAlgorithmException ex) {
771	            throw new IllegalStateException("SHA-256 not available", ex);
772	        }
773	    }
774	
775	    /**
776	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
777	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
778	     * result is lower-cased. A {@code null} value normalizes to the empty string.
779	     *
780	     * @param value the value to normalize, may be {@code null}
781	     * @return the normalized value
782	     */
783	    private String normalizeForComparison(String value) {
784	        if (value == null) {
785	            return "";
786	        }
787	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
788	    }
789	
790	    /**
791	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
792	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
793	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
794	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
795	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
796	     * that is stored, returned, and used for every address comparison (household duplicate detection
797	     * and the shared household id).
798	     *
799	     * @param address the raw address value from the submitted owner payload, may be {@code null}
800	     * @return the normalized address
801	     */
802	    private String normalizeAddress(String address) {
803	        if (address == null) {
804	            return "";
805	        }
806	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
807	        if (collapsed.isEmpty()) {
808	            return "";
809	        }
810	        String[] tokens = collapsed.split(" ");
811	        StringBuilder normalized = new StringBuilder();
812	        for (int i = 0; i < tokens.length; i++) {
813	            if (i > 0) {
814	                normalized.append(' ');
815	            }
816	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
817	        }
818	        return normalized.toString();
819	    }
820	}
