58	    /**
59	     * Computes the owner's check digit: a single Luhn check digit (0-9) over the digits contained
60	     * in the owner's customer code. Returns {@code null} when the customer code is absent.
61	     */
62	    default Integer checkDigit(Owner owner) {
63	        String customerCode = owner.getCustomerCode();
64	        if (customerCode == null) {
65	            return null;
66	        }
67	        int sum = 0;
68	        boolean dbl = true;
69	        for (int i = customerCode.length() - 1; i >= 0; i--) {
70	            char c = customerCode.charAt(i);
71	            if (c < '0' || c > '9') {
72	                continue;
73	            }
74	            int d = c - '0';
75	            if (dbl) {
76	                d *= 2;
77	                if (d > 9) {
78	                    d -= 9;
79	                }
80	            }
81	            sum += d;
82	            dbl = !dbl;
83	        }
84	        return (10 - (sum % 10)) % 10;
85	    }
86	
87	    /**
88	     * Derives the owner's duplicate-detection identity key, formatted
89	     * {@code '<normalizedTelephone>|<email>|<householdId>'}. The email and household-id segments are
90	     * empty when the respective field is absent. The telephone and email are already stored in their
91	     * normalized (E.164 / lower-cased) form, so the stored values are used directly. This is the single
92	     * key against which owner duplicates are detected: two owners collide only when their whole keys
93	     * match.
94	     */
95	    default String identityKey(Owner owner) {
96	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
97	        String email = owner.getEmail() == null ? "" : owner.getEmail();
98	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
99	        return telephone + "|" + email + "|" + householdId;
100	    }
101	
102	    /**
103	     * Fixed city-to-region table used to derive an owner's locality.
104	     */
105	    java.util.Map<String, String> CITY_REGION =
106	        java.util.Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
107	
108	    /**
109	     * Inclusive 4-digit postcode range {@code [low, high]} owned by each region: NSW 2000-2099,
110	     * VIC 3000-3099, QLD 4000-4099. Used to resolve an owner's region from the postcode first.
111	     */
112	    java.util.Map<String, int[]> REGION_POSTCODES =
113	        java.util.Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
114	
115	    /**
116	     * Derives the owner's locality, the {@code REGION} segment of the owner's customer code (the
117	     * region-and-hash identity {@code '<REGION>-<HASH8>'}). Only when no customer code is present does
118	     * it fall back to deriving the region directly, preferring the postcode's {@link #REGION_POSTCODES}
119	     * range and then the fixed {@link #CITY_REGION} city table. Returns the canonical region string, or
120	     * {@code "UNKNOWN"} when neither source resolves a region.
