135	                for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
136	                    int[] range = entry.getValue();
137	                    if (value >= range[0] && value <= range[1]) {
138	                        return entry.getKey();
139	                    }
140	                }
141	            }
142	            catch (NumberFormatException ex) {
143	                // Not a numeric postcode; fall back to the city table below.
144	            }
145	        }
146	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
147	    }
