151	     */
152	    java.util.Map<String, String> REGION_TIMEZONE =
153	        java.util.Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
154	
155	    /**
156	     * Derives the owner's timezone as an IANA name from the owner's {@link #locality(Owner) locality}
157	     * (region) via the fixed {@link #REGION_TIMEZONE} table: {@code NSW -> Australia/Sydney},
