219	     * is present, {@code 1} when the owner has no namesakes ({@code namesakeCount} is {@code 0}),
220	     * {@code 2} for a household of {@code 3} or more ({@code householdSize}), and {@code 3} when the
221	     * owner's tenure exceeds {@code 365} days (measured from the {@code registrationDate} to the
222	     * current date).
223	     */
224	    default Integer membershipPoints(Owner owner) {
225	        Integer namesakeCount = owner.getNamesakeCount();
226	        String email = owner.getEmail();
227	        Integer householdSize = owner.getHouseholdSize();
228	        int points = 0;
229	        if (email != null && !email.isBlank()) {
